  "inlineSchema": "// Database schema for the Mai Ru dating app: genders, users (profile and target preferences),\n// sign-in methods, refresh tokens, target genders, messages, favorites and notes.\n// Needs PostgreSQL 18 or newer for uuidv7(). The database URL is set in prisma.config.ts.\n// Database names stay snake_case (@map / @@map); Prisma names are camelCase and PascalCase.\n// onUpdate: NoAction keeps Postgres's default ON UPDATE rule (Prisma's own default is Cascade).\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n  runtime  = \"bun\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n/// One gender option, used for a user's own gender and for target genders.\n/// The four rows (female, male, non_binary, prefer_not_to_say) come from the migrations: the\n/// first one added male, female, non_binary and other; the second replaced other.\nmodel Gender {\n  code  String @id @db.VarChar(20)\n  label String @db.VarChar(50)\n\n  users      User[]\n  targetedBy UserTargetGender[]\n\n  @@map(\"genders\")\n}\n\n/// One person: username, profile and target preferences.\nmodel User {\n  id             String   @id @default(dbgenerated(\"uuidv7()\")) @db.Uuid\n  /// Saved in lowercase by the backend, so the unique rule also catches \"Alice\" vs \"alice\".\n  username       String   @unique @db.VarChar(30)\n  displayName    String   @map(\"display_name\") @db.VarChar(50)\n  dateOfBirth    DateTime @map(\"date_of_birth\") @db.Date\n  genderCode     String   @map(\"gender_code\") @db.VarChar(20)\n  /// RustFS object key of the profile photo: `profile-photos/<photoId>.<extension>`, where photoId\n  /// is a UUID. Unique, so GET /photos/{photoId} finds exactly one user.\n  photoKey       String   @unique @map(\"photo_key\") @db.VarChar(255)\n  latitude       Float\n  longitude      Float\n  /// \"province, district\" in English, e.g. \"Bangkok, Pathum Wan\" (only the province when no\n  /// district is known). Empty when the lookup failed.\n  placeName      String?  @map(\"place_name\") @db.VarChar(100)\n  targetMinAge   Int      @map(\"target_min_age\") @db.SmallInt\n  targetMaxAge   Int      @map(\"target_max_age\") @db.SmallInt\n  targetRadiusKm Int      @map(\"target_radius_km\")\n  createdAt      DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt      DateTime @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  gender           Gender             @relation(fields: [genderCode], references: [code], onDelete: Restrict, onUpdate: NoAction)\n  targetGenders    UserTargetGender[]\n  authMethods      UserAuthMethod[]\n  refreshTokens    RefreshToken[]\n  sentMessages     Message[]          @relation(\"MessageSender\")\n  receivedMessages Message[]          @relation(\"MessageReceiver\")\n  favorites        Favorite[]         @relation(\"FavoriteOwner\")\n  favoritedBy      Favorite[]         @relation(\"FavoriteTarget\")\n  notesWritten     Note[]             @relation(\"NoteAuthor\")\n  notesAbout       Note[]             @relation(\"NoteSubject\")\n\n  @@map(\"users\")\n}\n\n/// One way a user can sign in. Only \"password\" for now (passwordHash set); \"google\"\n/// (providerUserId set) may come later with no table change.\nmodel UserAuthMethod {\n  userId         String  @map(\"user_id\") @db.Uuid\n  authType       String  @map(\"auth_type\") @db.VarChar(20)\n  /// Argon2id hash from Bun.password. Never sent to the app.\n  passwordHash   String? @map(\"password_hash\") @db.VarChar(255)\n  providerUserId String? @map(\"provider_user_id\") @db.VarChar(255)\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@id([userId, authType])\n  @@unique([authType, providerUserId])\n  @@map(\"user_auth_methods\")\n}\n\n/// One refresh token given out at sign-up, login or refresh. Only its hash is stored.\nmodel RefreshToken {\n  id        String    @id @default(dbgenerated(\"uuidv7()\")) @db.Uuid\n  userId    String    @map(\"user_id\") @db.Uuid\n  /// SHA-256 of the token as 64 lowercase hex characters. Never sent to the app.\n  tokenHash String    @unique @map(\"token_hash\") @db.Char(64)\n  createdAt DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  expiresAt DateTime  @map(\"expires_at\") @db.Timestamptz(6)\n  /// Empty means the token has not been revoked.\n  revokedAt DateTime? @map(\"revoked_at\") @db.Timestamptz(6)\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@index([userId])\n  @@map(\"refresh_tokens\")\n}\n\n/// \"This user wants to see this gender\". \"Anyone\" is one row for every gender.\nmodel UserTargetGender {\n  userId     String @map(\"user_id\") @db.Uuid\n  genderCode String @map(\"gender_code\") @db.VarChar(20)\n\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  gender Gender @relation(fields: [genderCode], references: [code], onDelete: Restrict, onUpdate: NoAction)\n\n  @@id([userId, genderCode])\n  @@map(\"user_target_genders\")\n}\n\n/// One text message from one user to another, optionally a reply to an earlier message.\nmodel Message {\n  id               String    @id @default(dbgenerated(\"uuidv7()\")) @db.Uuid\n  senderId         String    @map(\"sender_id\") @db.Uuid\n  receiverId       String    @map(\"receiver_id\") @db.Uuid\n  body             String    @db.VarChar(1000)\n  replyToMessageId String?   @map(\"reply_to_message_id\") @db.Uuid\n  sentAt           DateTime  @default(now()) @map(\"sent_at\") @db.Timestamptz(6)\n  /// Empty means the receiver has not read the message yet.\n  readAt           DateTime? @map(\"read_at\") @db.Timestamptz(6)\n\n  sender   User      @relation(\"MessageSender\", fields: [senderId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  receiver User      @relation(\"MessageReceiver\", fields: [receiverId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  replyTo  Message?  @relation(\"MessageReply\", fields: [replyToMessageId], references: [id], onDelete: SetNull, onUpdate: NoAction)\n  replies  Message[] @relation(\"MessageReply\")\n\n  @@index([receiverId, readAt])\n  @@index([senderId, receiverId, sentAt])\n  @@map(\"messages\")\n}\n\n/// \"This user pinned that user\". Favorites are shown first in the chat list.\nmodel Favorite {\n  userId         String   @map(\"user_id\") @db.Uuid\n  favoriteUserId String   @map(\"favorite_user_id\") @db.Uuid\n  createdAt      DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n\n  user         User @relation(\"FavoriteOwner\", fields: [userId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  favoriteUser User @relation(\"FavoriteTarget\", fields: [favoriteUserId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@id([userId, favoriteUserId])\n  @@map(\"favorites\")\n}\n\n/// One private note a user wrote about another user. Many notes per pair are allowed.\nmodel Note {\n  id            Int      @id @default(autoincrement())\n  authorId      String   @map(\"author_id\") @db.Uuid\n  subjectUserId String   @map(\"subject_user_id\") @db.Uuid\n  body          String   @db.VarChar(2000)\n  createdAt     DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt     DateTime @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  author      User @relation(\"NoteAuthor\", fields: [authorId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  subjectUser User @relation(\"NoteSubject\", fields: [subjectUserId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@index([authorId, subjectUserId, createdAt])\n  @@map(\"notes\")\n}\n",
